# single words too common to identify one concept when they appear in a question
GENERIC = {"market", "limit", "stop", "spread", "equity", "risk", "growth", "yield", "earnings", "carry", "value", "quality", "costs", "multiple",
           "power", "selling", "range", "position", "variance", "skew", "luck", "skill", "anchor", "fair", "speed", "cycle", "variance", "tell"}


def concepts() -> list[dict]:
    out = []
    for row in RAW:
        cid, name, cluster, text, rels, formula, aka = row
        rel = []
        for part in (rels or "").split(";"):
            part = part.strip()
            if not part:
                continue
            kind, targets = part.split(":", 1)
            for t in targets.split(","):
                t = t.strip()
                if t:
                    rel.append((kind.strip(), t))
        out.append({"id": "c:" + cid, "name": name, "cluster": cluster, "text": text, "formula": formula, "aliases": [a.strip() for a in (aka or "").split(",") if a.strip() and a.strip().lower() not in GENERIC], "rel": rel})
    return out
